<?php require '../common.php'; startpage('Library Management System'); nav('<a href="index.php">Catalog</a><a href="admin.php">Librarian Admin</a><a href="history.php">Borrow history / fine</a><a href="materials.php">Study materials</a>'); 
if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['search'])){$q='%'.$_POST['q'].'%';$s=$conn->prepare('SELECT * FROM books WHERE title LIKE ? OR author LIKE ? OR category LIKE ?');$s->bind_param('sss',$q,$q,$q);$s->execute();$rs=$s->get_result();}else{$rs=$conn->query('SELECT * FROM books');} ?>
<form method="post"><input name="q" placeholder="Search title, author, category"><button name="search">Search</button></form>
<table><tr><th>Title</th><th>Author</th><th>Category</th><th>Available</th><th>Issue</th></tr><?php while($b=$rs->fetch_assoc()):?><tr><td><?=e($b['title'])?></td><td><?=e($b['author'])?></td><td><?=e($b['category'])?></td><td><?=$b['available']?></td><td><a href="issue.php?id=<?=$b['id']?>">Issue</a></td></tr><?php endwhile;?></table><?php endpage();?>